import React, { useEffect, useState } from 'react';
import { useParams } from 'react-router-dom';
import { Button } from '@/components/ui/button';
import { motion } from 'framer-motion';
import { useNavigate } from 'react-router-dom';
import jsPDF from 'jspdf';
import autoTable from 'jspdf-autotable';
import { FileDown } from 'lucide-react';
import { PlusCircle } from "lucide-react";
import { db } from '../firebaseConfig'; // 👈 AJUSTAr la ruta si es necesario
import { doc, getDoc } from 'firebase/firestore';
import { toast } from '@/components/ui/use-toast';
//IMPORTS CREADOS PARA PESTAÑAS
import HojaDeAnestecia    from '@/components/pestañas/HojaDeAnestecia';
import RegistroAnestesico from '@/components/pestañas/RegistroAnestesico';
import RegistroInfusiones from '@/components/pestañas/RegistroInfusiones';


export const RegAnestesia = () => {
  const { mainId } = useParams();
  const [time, setTime] = useState(new Date());
  const [admisiones, setAdmisiones] = useState(null); // <-- aquí se guardan los datos desde Firestore
  const [loading, setLoading] = useState(true);
  const navigate = useNavigate();
  //CONSTANTE PARA ACTIVAR Y DESCATIVAR PESTAÑAS
  const [activeTab, setActiveTab] = useState('hojaA');
  //agregado 
 
const [agentesTexto, setAgentesTexto] = useState('sdas');


//SE GENERA UN PDF
const [formData, setFormData] = useState({
  tipoCirugia: '',
  cirujano1: '',
  cirujano2: '',
  anestesiologo: '',
  ayudante1: '',
  pediatra: '',
  horaInicio: '',
  horaFin: '',
  peso: '',
  talla: '',
  sexo: '',
  tipoAnestesia: '',
  sala: '',
  operacion: '',
  diagnosticoCodigo: 'Q35',
  diagnosticoDescripcion: 'APENDICITIS AGUDA',
  agentes: '',
  infusiones: '',
  ingreso: 'CC',
  egreso: 'CC',
  farmacos: '',
  insumos: '',
  viaArea: '',
  posicion: '',
  tecnica: '',
  conducidoA: '',
  comentarios: ''
});

const handleGeneratePDF = () => {
  const doc = new jsPDF('p', 'mm', 'a4');
  
  const imgData = 'data:image/png;base64,';

  // recorta por brevedad
  // Agregar imagen: (imgData, tipo, x, y, width, height)
  doc.addImage(imgData, 'PNG', 10, 10, 40, 15);

  doc.setFontSize(10);
  doc.setFontSize(14);
  doc.text('REGISTRO DE ANESTESIA', 80, 10);

  doc.setFontSize(8);
  doc.text(`FECHA: ${formattedDate}`, 55, 18);

  doc.text(`PACIENTE: ALCIVAR ROMERO DAVID ERNESTO`, 55, 24);
  
  doc.text(`EDAD: 41`, 55, 30);
  doc.text(`CEDULA: 1713656748`, 130, 18);
  doc.text(`SEGURO: HUMANA`, 130, 24);
  doc.text(`HCL: 1713656748`, 130, 30);
  doc.text(`CIRUJIA: EMERGENCIA`, 170, 18);
  

  doc.line(10, 40, 200, 40);

  autoTable(doc, {
    startY:  45,
    head: [['CIRUJANO 1','AYUDANTE 1', 'ANESTESIOLOGO', 'PESO', 'TALLA', 'SALA', '  ']],
    headStyles: 
    { fillColor: '#FFFFFF', 
    textColor: '#000000',
    halign: 'center',
    fontStyle: 'bold',
    fontSize: 5
   },
    body: [[' ', ' ', ' ', '70 KG', '1.60',  '1', 'HCL 1713656748']],
    bodyStyles: {
      halign: 'center',
      fontSize: 6
    },
    columnStyles: {
      0: { cellWidth: 25 },
      1: { cellWidth: 25 },
      2: { cellWidth: 25 },
      3: { cellWidth: 25 },
      4: { cellWidth: 25 },
      5: { cellWidth: 25 },
      6: { cellWidth: 25 }
    },
    styles: {
      cellPadding: 4,
      lineColor: [0, 0, 0],
      lineWidth: 0.2
    },
    theme: 'grid' // para mostrar bordes
  });
  autoTable(doc, {
    startY:  65,
    head: [['CIRUJANO 2','AYUDANTE 2', ' AYU. ANESTESIOLOGO', 'PEDIATRA', 'SERVICIO']],
    headStyles: 
    { fillColor: '#FFFFFF', 
    textColor: '#000000',
    halign: 'center',
    fontStyle: 'bold',
    fontSize: 5
   },
    body: [[' ', ' ', ' ', ' ', 'TRAUMATOLOGIA']],
    bodyStyles: {
      halign: 'center',
      fontSize: 6
    },
    columnStyles: {
      0: { cellWidth: 35 },
      1: { cellWidth: 35 },
      2: { cellWidth: 35 },
      3: { cellWidth: 35 },
      4: { cellWidth: 35 }
      
    },
    styles: {
      cellPadding: 4,
      lineColor: [0, 0, 0],
      lineWidth: 0.2
    },
    theme: 'grid' // para mostrar bordes
  });

 doc.text(`FÁRMACOS: ${formData.farmacos}`, 10, 104);
  doc.text(`INFUSIONES: ${formData.infusiones}`, 10, 110);
  doc.text(`INSUMOS: ${formData.insumos}`, 10, 116);

  doc.text(`MANEJO VÍA AÉREA: ${formData.viaArea}`, 10, 122);
  doc.text(`POSICIÓN: ${formData.posicion}`, 10, 128);

  doc.text(`TÉCNICA: ${formData.tecnica}`, 10, 134);
  doc.text(`CONDUCIDO A: ${formData.conducidoA}`, 10, 140);
  doc.text(`COMENTARIOS: ${formData.comentarios}`, 10, 146);

   doc.text('FIRMA Y SELLO', 150, 280);

  doc.save('registro-anestesia.pdf');
};
  

  useEffect(() => {
    const timer = setInterval(() => setTime(new Date()), 1000);
    return () => clearInterval(timer);
  }, []);
//Aqui traigo de firebase para el encabezado
useEffect(() => {
  const fetchAdmisiones = async () => {
    console.log('🧪 mainId recibido:', mainId);

    if (!mainId) {
      console.warn('⚠️ mainId es undefined o null'); 
      setLoading(false);
      return;
    }
    try {
      const ref = doc(db, 'admisiones', mainId);
      const snap = await getDoc(ref);
         if (!snap.exists()) {
        console.warn('❌ Documento no existe');
        setAdmisiones(null);
        return;
      }
      const data = snap.data();
         setAdmisiones({
            id: snap.id,
            ...data,
            ...data.mainData,
          });
        } catch (error) {
      console.error('❌ Error al obtener admisiones:', error);
      setAdmisiones(null);
    } finally {
      setLoading(false);
    }
  };
  fetchAdmisiones();
}, [mainId]);
//hasta aqui traigo de firebase
  const formattedDate = time.toLocaleDateString('es-ES', {
    weekday: 'long', year: 'numeric', month: 'long', day: 'numeric'
  });
  const formattedTime = time.toLocaleTimeString('es-ES');

  return (
    <div className="min-h-screen bg-gradient-to-br from-[#ffffff] via-[#EAF4FB] to-[#1a5784]">
      <div className="relative mb-2">
      <button
          onClick={() => window.history.back()}
          className="absolute left-0 top-1/2 -translate-y-1/2 rounded-lg bg-[#1c3f6e] px-3 py-1.5 text-sm font-semibold text-white shadow transition hover:bg-[#007e8f]"
        >
          ← Volver
        </button>
        <h1 className="text-2xl text-[#007e8f] font-extrabold tracking-wide text-center">REGISTRO DE ANESTESIA</h1>
        </div>
      {/* ++++++++++++++++++++++++++++++++++++++++++++++++++++++++HEADER++++++++++++++++++++++++++++++++++++++++++ */}
      <header className="relative rounded-2xl border border-[#007e8f]/25 bg-white/85 p-2 md:p-3 shadow-md text-[#1c3f6e] backdrop-blur">
      <div className="grid grid-cols-1 md:grid-cols-3 gap-6 text-xs items-start">



          {/* ================= IZQUIERDA ================= */}
          <div className="flex flex-col items-start space-y-3">
          <img
            src="https://clinicas-atlas.com/wp-content/uploads/2024/11/clinicas-atlas-ecuador.png"
            alt="Logo Clinica Atlas"
            className="w-36 h-auto mcx-auto mb-4"
          />
         {/* Hora */}
      <p className="text-sm font-bold">
        {formattedTime}
      </p>

      {/* Fecha */}
      <p className="text-xs uppercase tracking-wide">
        {formattedDate?.toUpperCase()}
      </p>

        </div>

        

{/* 🔄 Mostrar datos del citas o cargando */}
<div className="text-xs grid grid-cols-1 md:grid-cols-2">
{loading ? (
              <p className="text-gray-600">Cargando datos de admisiones...</p>
            ) : admisiones ? (
              <>
                <div>
                  <strong>{admisiones.firstName} {admisiones.lastName}{' '} </strong><br/>
                  <strong>Identificacion:</strong> {admisiones.cedula}<br/>
                  <strong>Edad:</strong> {admisiones.seguro}<br/>
                   <strong>Médico:</strong> {admisiones.medico}<br/>
                   <strong>Fecha Nacimiento:</strong> {admisiones.secondaryData?.dateOfBirth || 'No registrado'}   <br/>
                   <strong>Días de estancia:</strong> {admisiones.dias}<br/>
                  
                </div>
                <div>
                <strong>Servicio:</strong> {admisiones.servicio}<br/>
                  <strong>Seguro:</strong> {admisiones.seguro}<br/>
                  <strong>Alertas:</strong> {admisiones.alergiaIconUno || 'No registrado'} {admisiones.alergiaUno || 'No registrado'}   <br/>
                  {admisiones.alergiaIconDos || ''} {admisiones.alergiaDos || ''} <br/>
                  {admisiones.alergiaIconTres || ''} {admisiones.alergiaTres || ''}
                   </div>
                   <div className=" bg-[#007e8f]/90 absolute rounded text-center p-4 text-white font-bold top-30 right-10">
                <strong>PISO:</strong> {admisiones.ubicacion.piso ||'No Reg'} <br/>
                  <strong></strong> {admisiones.ubicacion.habitacion ||'No Reg'} <br/>
                </div>
                
              </>
            ) : (
              <p className="text-red-600 font-bold">
                ❌ No se encontró información de admisiones.estoy arto
              </p>
            )}

            {/*HASTA AQUI DE FIREBASE */}
            </div>

  {/* ================= DERECHA (PISO / HAB) ================= */}
     
  <div className="flex justify-center mt-6">
                  <Button
  onClick={handleGeneratePDF}
  className="bg-[#0b4f6c]/70 text-white px-7 py-2 rounded hover:bg-[#87D1D4] flex items-center"
  title="Imprimir PDF"
>
  <img
    src="https://cdn-icons-png.flaticon.com/512/4659/4659495.png"
    alt="Imprimir"
    className="w-6 h-6"
  />
</Button>
</div>
        </div>
      </header>

      

      {/* MAIN PANEL */}
      <main className="grid grid-cols-1 md:grid-cols-6 gap-4 mt-3 ">





        {/* LEFT PANEL */}
<div className="bg-[#4b6bb3]/10 rounded shadow p-4">
  <div className="flex justify-between items-center bg-[#007e8f] text-white text-center text-xs font-bold px-4 py-2 rounded-t">
    <h2>REGISTROS DE ANESTESIA</h2>
    <button 
      onClick={() => console.log("Agregar nuevo registro")} 
      className="text-black hover:text-gray-50"
      title="Agregar nuevo registro"
    >
      <PlusCircle className="w-5 h-5" />
    </button>
  </div>

  {/* Fecha debajo del encabezado */}
  <div className="rounded shadow p-1 text-base text-center text-gray bg-[#007e8f] font-semibold mt-8 max-w-fit mx-auto">
  Fecha: 23/11/2023
</div>

{/* Botones Editar y Guardar */}
  <div className="mt-60 ml-2 flex gap-3 ">
    <button 
      onClick={() => console.log("Editar")}
      className="px-1 py-2 text-sx bg-[#007e8f] font-bold text-gray rounded hover:bg-green-500"
    >
      EDITAR
    </button>
    <button 
      onClick={() => console.log("Guardar")}
      className="px-3 py-1 text-sx bg-[#007e8f] text-white font-bold rounded hover:bg-[#0b4f6c]"
    >
      GUARDAR
    </button>
  </div>
</div>






        
        {/* ++++++++++++++++++++++++++++++++++++++++++++++++++RIGHT PANEL +++++++++++++++++++++++++++++++++++++++++++++++++++ */}
          {/* RIGHT PANEL */}
          <div className="md:col-span-5 bg-white rounded shadow p-1">
            {/* CONTENEDOR FLEX */}
            <div className="flex">
              {/* CONTENIDO DINÁMICO */}
              <div className="flex-1 pr-1">
                {activeTab === 'hojaA' && <HojaDeAnestecia />}
                {activeTab === 'registroAnestesico' && <RegistroAnestesico />}
                {activeTab === 'registroInfusiones' && <RegistroInfusiones />}
                
              </div>
              {/* PESTAÑAS VERTICALES */}
              <div className="w-48 border-l pl-3 flex flex-col text-black gap-2">
                <button
                  onClick={() => setActiveTab('hojaA')}
                  className={`px-5 py-5 text-xs font-bold rounded transition ${
                    activeTab === 'hojaA'
                      ? 'bg-gradient-to-r from-[#007e8f] via-[#007090]/90 to-[#0080ff]/10 text-white'
                      : 'bg-gray-100 hover:bg-gray-200'
                  }`}
                >
                  📋 Hoja de Anestesia
                </button>
                <button
                  onClick={() => setActiveTab('registroAnestesico')}
                  className={`px-1 py-5 text-xs font-bold rounded transition ${
                    activeTab === 'registroAnestesico'
                      ? 'bg-gradient-to-r from-[#007e8f] via-[#007090]/90 to-[#0080ff]/10 text-white'
                      : 'bg-gray-100 hover:bg-gray-200'
                  }`}
                >
                  🩺 Registro Anestesico
                </button>
                <button
                  onClick={() => setActiveTab('registroInfusiones')}
                  className={`px-5 py-5 text-xs font-bold rounded transition ${
                    activeTab === 'registroInfusiones'
                      ? 'bg-gradient-to-r from-[#007e8f] via-[#007090]/90 to-[#0080ff]/10 text-white'
                      : 'bg-gray-100 hover:bg-gray-200'
                  }`}
                >
                  ⚖️ Riesgo Infusiones
                </button>
                
              </div>
            </div>
          </div>
          {/* ++++++++++++++++hasta aqui++++++++++++++++++++++++++++++++++RIGHT PANEL +++++++++++++++++++++++++++++++++++++++++++++++++++ */}














      </main>
    </div>
  );
};

export default RegAnestesia;
